"""Authenticated development WSGI case intake; not a notarial authorization endpoint.

The authentication adapter must independently validate an external identity token.
No trust is placed in caller-supplied user headers, role labels or payment status.
"""
import json
import re
from .cases import CaseDenied

MAX_BODY = 8192
CASE_PATH = re.compile(r'^/v1/cases/([A-Za-z0-9_.-]{1,128})$')

class APIConfigurationError(Exception):
    pass

def create_app(registry, authenticate):
    if not callable(authenticate):
        raise APIConfigurationError('Independent authentication adapter required')

    def respond(start_response, status, payload):
        body = json.dumps(payload, separators=(',', ':')).encode('utf-8')
        start_response(status, [('Content-Type','application/json'),
                                ('Content-Length',str(len(body))),
                                ('Cache-Control','no-store'),
                                ('X-Content-Type-Options','nosniff')])
        return [body]

    def app(environ, start_response):
        path = environ.get('PATH_INFO','')
        method = environ.get('REQUEST_METHOD','')
        if not isinstance(path,str) or not isinstance(method,str):
            return respond(start_response,'400 Bad Request',{'error':'invalid_request'})
        if path != '/v1/cases' and not CASE_PATH.fullmatch(path):
            return respond(start_response,'404 Not Found',{'error':'not_found'})
        if (path == '/v1/cases' and method != 'POST') or (path != '/v1/cases' and method != 'GET'):
            return respond(start_response,'405 Method Not Allowed',{'error':'method_not_allowed'})
        try:
            identity = authenticate(environ)
        except Exception:
            identity = None
        if not isinstance(identity,str) or not re.fullmatch(r'[A-Za-z0-9_.-]{1,128}',identity):
            return respond(start_response,'401 Unauthorized',{'error':'unauthorized'})
        if method == 'POST':
            length = environ.get('CONTENT_LENGTH','')
            if not isinstance(length,str) or not length.isdigit() or not 0 < int(length) <= MAX_BODY:
                return respond(start_response,'413 Content Too Large',{'error':'invalid_length'})
            if environ.get('CONTENT_TYPE','').split(';')[0].strip().lower() != 'application/json':
                return respond(start_response,'415 Unsupported Media Type',{'error':'json_required'})
            try:
                raw = environ['wsgi.input'].read(int(length))
                if len(raw) != int(length):
                    raise ValueError('short body')
                data = json.loads(raw)
                if not isinstance(data,dict) or set(data) != {'case_id','jurisdiction','service'}:
                    raise ValueError('unexpected fields')
                record = registry.create(data['case_id'],data['jurisdiction'],data['service'],identity)
            except (ValueError,TypeError,KeyError,UnicodeError,CaseDenied):
                return respond(start_response,'400 Bad Request',{'error':'case_denied'})
            return respond(start_response,'201 Created',{'case':record})
        match = CASE_PATH.fullmatch(path)
        try:
            record = registry.get(match.group(1))
        except (ValueError,TypeError,CaseDenied):
            return respond(start_response,'404 Not Found',{'error':'not_found'})
        if not record or record.get('requester') != identity:
            return respond(start_response,'404 Not Found',{'error':'not_found'})
        return respond(start_response,'200 OK',{'case':record})
    return app

core_platform/cases.py.content:
"""Sanders Dash & Seal case intake foundation: no simulated notarial authority."""
import re
import sqlite3
import time
from .upgrade_sidecar import require_core_laws

class CaseDenied(Exception):
    pass

class CaseRegistry:
    """Persistent, fail-closed case intake; authorization is never inferred from payment."""
    def __init__(self, db_path, core_laws):
        require_core_laws(core_laws)
        self.db_path = str(db_path)
        with sqlite3.connect(self.db_path) as db:
            db.execute('''CREATE TABLE IF NOT EXISTS cases
                (case_id TEXT PRIMARY KEY, jurisdiction TEXT NOT NULL,
                 service TEXT NOT NULL, requester TEXT NOT NULL,
                 status TEXT NOT NULL, created_at INTEGER NOT NULL)''')

    def create(self, case_id, jurisdiction, service, requester, *, connection=None):
        if (not all(isinstance(x, str) and re.fullmatch(r'[A-Za-z0-9_.-]{1,128}', x)
                    for x in (case_id, jurisdiction, requester))
                or service not in ('MOBILE_NOTARY', 'E_NOTARY', 'RON', 'AUTHORIZED_DOCUMENT_SERVICE')):
            raise CaseDenied('Invalid case identity, jurisdiction or service')
        if connection is not None:
            return self._insert(connection, case_id, jurisdiction, service, requester)
        with sqlite3.connect(self.db_path) as db:
            return self._insert(db, case_id, jurisdiction, service, requester)

    @staticmethod
    def _insert(db, case_id, jurisdiction, service, requester):
        try:
            db.execute('INSERT INTO cases VALUES (?,?,?,?,?,?)',
                       (case_id, jurisdiction, service, requester,
                        'AWAITING_HUMAN_AUTHORITY_REVIEW', int(time.time())))
        except sqlite3.IntegrityError as exc:
            raise CaseDenied('Duplicate case') from exc
        return dict(case_id=case_id, jurisdiction=jurisdiction, service=service,
                    requester=requester, status='AWAITING_HUMAN_AUTHORITY_REVIEW')

    def get(self, case_id):
        with sqlite3.connect(self.db_path) as db:
            row = db.execute('SELECT case_id,jurisdiction,service,requester,status FROM cases WHERE case_id=?',
                             (case_id,)).fetchone()
        if not row:
            raise CaseDenied('Unknown case')
        return dict(zip(('case_id','jurisdiction','service','requester','status'), row))

    def authorize_notarization(self, *args, **kwargs):
        raise CaseDenied('Independent human identity, commission, jurisdiction and provider verification not connected')

core_platform/customer_app.py.content:
"""Customer interface over existing case, appointment and payment components.

Authentication is an injected independent session verifier, never a user header.
Production startup must be externally verified; default API behavior is denial.
The auth application owns OIDC/session cookies, login CSRF and logout behavior.
"""
import json
import re
from pathlib import Path
from urllib.parse import urlsplit
from .appointments import AppointmentDenied, IDENT
from .cases import CaseDenied
from .stripe_payments import PaymentDenied

ASSETS = {'/auth/login': ('auth.html', 'text/html; charset=utf-8'),
          '/auth/register': ('auth.html', 'text/html; charset=utf-8'),
          '/auth/setup': ('auth.html', 'text/html; charset=utf-8'),
          '/auth/logout': ('auth.html', 'text/html; charset=utf-8'),
          '/assets/auth.js': ('auth.js', 'application/javascript; charset=utf-8'), '/resources': ('resources.html', 'text/html; charset=utf-8'),
          '/assets/resources.js': ('resources.js', 'application/javascript; charset=utf-8'),
          '/': ('index.html', 'text/html; charset=utf-8'),
          '/appointments': ('index.html', 'text/html; charset=utf-8'),
          '/operator': ('operator.html', 'text/html; charset=utf-8'),
          '/assets/operator.js': ('operator.js', 'application/javascript; charset=utf-8'),
          '/assets/booking.css': ('booking.css', 'text/css; charset=utf-8'),
          '/assets/booking.js': ('booking.js', 'application/javascript; charset=utf-8')}
CASE_ROUTE = re.compile(r'/api/appointments/([A-Za-z0-9_.-]{1,128})(/checkout)?')
OPERATOR_ROUTE = re.compile(r'/api/operator/appointments/([A-Za-z0-9_.-]{1,128})/quote')


def create_customer_app(appointments, authenticate, payments, auth_app, site_origin,
                        *, release_verifier=lambda: False):
    origin = urlsplit(site_origin)
    if (origin.scheme != 'https' or not origin.netloc or origin.path
            or origin.query or origin.fragment or origin.username
            or not all(callable(v) for v in (authenticate, auth_app, release_verifier))):
        raise ValueError('Trusted origin and independent authentication adapters required')
    root = Path(__file__).resolve().parent.parent / 'web'

    def respond(start, status, data, content_type='application/json'):
        body = data if isinstance(data, bytes) else json.dumps(data).encode()
        start(status, [('Content-Type', content_type), ('Content-Length', str(len(body))),
            ('Cache-Control', 'no-store'), ('X-Content-Type-Options', 'nosniff'),
            ('Referrer-Policy', 'no-referrer'), ('X-Frame-Options', 'DENY'),
            ('Content-Security-Policy', "default-src 'none'; script-src 'self'; style-src 'self'; "
             "connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'")])
        return [body]

    def app(env, start):
        path, method = env.get('PATH_INFO', ''), env.get('REQUEST_METHOD', '')
        if method == 'GET' and path in ASSETS:
            filename, mime = ASSETS[path]
            return respond(start, '200 OK', (root / filename).read_bytes(), mime)
        try:
            if release_verifier() is not True:
                return respond(start, '503 Service Unavailable', {'error': 'appointments_unavailable'})
        except Exception:
            return respond(start, '503 Service Unavailable', {'error': 'appointments_unavailable'})
        if path.startswith('/auth/'):
            return auth_app(env, start)
        match = CASE_ROUTE.fullmatch(path)
        operator_match = OPERATOR_ROUTE.fullmatch(path)
        is_operator_route = path == '/api/operator/appointments' or operator_match is not None
        if path not in ('/api/session', '/api/appointments') and not match and not is_operator_route:
            return respond(start, '404 Not Found', {'error': 'not_found'})
        allowed = ('GET', 'POST') if path == '/api/appointments' else (
            ('POST',) if operator_match or (match and match.group(2)) else ('GET',))
        if method not in allowed:
            return respond(start, '405 Method Not Allowed', {'error': 'method_not_allowed'})
        try:
            identity = authenticate(env)
        except Exception:
            identity = None
        if not isinstance(identity, str) or not IDENT.fullmatch(identity):
            return respond(start, '401 Unauthorized', {'error': 'sign_in_required'})
        if is_operator_route:
            try:
                authorized = payments.operator_verifier(identity) is True
            except Exception:
                authorized = False
            if not authorized:
                return respond(start, '403 Forbidden', {'error': 'operator_required'})
        data = None
        if method == 'POST':
            if env.get('HTTP_ORIGIN') != site_origin:
                return respond(start, '403 Forbidden', {'error': 'origin_denied'})
            if env.get('CONTENT_TYPE', '').split(';')[0].strip().lower() != 'application/json':
                return respond(start, '415 Unsupported Media Type', {'error': 'json_required'})
            try:
                length = env.get('CONTENT_LENGTH', '')
                if not isinstance(length, str) or not length.isdigit() or not 0 < int(length) <= 4096:
                    raise ValueError('length')
                raw = env['wsgi.input'].read(int(length))
                if len(raw) != int(length):
                    raise ValueError('short body')
                data = json.loads(raw)
                if not isinstance(data, dict):
                    raise ValueError('object required')
            except (ValueError, UnicodeError, KeyError, TypeError):
                return respond(start, '400 Bad Request', {'error': 'invalid_request'})
        try:
            if path == '/api/operator/appointments':
                return respond(start, '200 OK', {'appointments': appointments.list_for_operator()})
            if operator_match:
                if set(data) != {'items', 'expires_at'}:
                    raise ValueError('unexpected fields')
                quote = payments.approve_quote(operator_match.group(1), identity, **data)
                return respond(start, '201 Created', {'quote': quote})
            if path == '/api/session':
                return respond(start, '200 OK', {'authenticated': True})
            if path == '/api/appointments':
                if method == 'GET':
                    return respond(start, '200 OK', {'appointments': appointments.list_owned(identity)})
                expected = {'request_id', 'jurisdiction', 'service', 'requested_start', 'meeting_area', 'consent'}
                if set(data) != expected:
                    raise ValueError('unexpected fields')
                record = appointments.request(requester=identity, **data)
                return respond(start, '201 Created', {'appointment': record})
            case_id = match.group(1)
            # Ownership is checked before quote/payment queries.
            record = appointments.get(case_id, identity)
            if match.group(2):
                if set(data) != {'quote_id', 'accept_quote'}:
                    raise ValueError('unexpected fields')
                result = payments.checkout(case_id, identity, **data)
                return respond(start, '200 OK', result)
            return respond(start, '200 OK', {'appointment': record,
                'quote': payments.quote(case_id, identity), 'payment': payments.ledger.status(case_id)})
        except AppointmentDenied:
            return respond(start, '400 Bad Request' if path == '/api/appointments' else '404 Not Found',
                           {'error': 'appointment_unavailable'})
        except (ValueError, TypeError, KeyError, CaseDenied):
            return respond(start, '400 Bad Request', {'error': 'invalid_request'})
        except PaymentDenied:
            return respond(start, '409 Conflict', {'error': 'checkout_unavailable'})
        except Exception:
            return respond(start, '503 Service Unavailable', {'error': 'temporarily_unavailable'})
    return app

core_platform/deployment.py.content:
"""WSGI deployment boundary for the existing Sanders Dash & Seal application.

Default startup serves existing assets and diagnostics only. Trusted production
adapters are supplied by the administrator, behind an external verified bootstrap.
Neither environment configuration nor an HTTP request grants production authority.
"""
from dataclasses import dataclass, replace
import importlib
import json
import re

from .customer_app import create_customer_app
from .free_resources import catalog as free_resource_catalog
from .pipeline_api import create_pipeline_app, TransactionStore
from .stream_api import create_stream_app


CANONICAL_HOST = 'sandersdashandseal.com'
ALIAS_HOSTS = ('www.sandersdashandseal.com', 'sanderslegalhelpersllc.com',
               'www.sanderslegalhelpersllc.com')
ORIGIN = 'https://' + CANONICAL_HOST
FACTORY = re.compile(r'[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*:[A-Za-z_]\w*', re.ASCII)


class DeploymentConfigurationError(ValueError):
    pass


@dataclass(frozen=True)
class RuntimeBindings:
    appointments: object
    payments: object
    authenticate: object
    auth_app: object
    release_verifier: object
    webhook_app: object = None
    transaction_processor: object = None
    transaction_store: object = None
    stream_verifiers: object = None


def _response(start, status, payload, extra=()):
    body = json.dumps(payload, separators=(',', ':')).encode()
    start(status, [('Content-Type', 'application/json'),
                   ('Content-Length', str(len(body))),
                   ('Cache-Control', 'no-store'),
                   ('X-Content-Type-Options', 'nosniff'),
                   ('Referrer-Policy', 'no-referrer'), *extra])
    return [body]


def _unavailable(env, start):
    return _response(start, '503 Service Unavailable', {'error': 'service_unavailable'})


def _denied():
    return False


def create_application(bindings=None):
    """Compose existing components; no bindings means diagnostic-only startup."""
    if bindings is not None:
        if (not isinstance(bindings, RuntimeBindings)
                or bindings.appointments is None or bindings.payments is None
                or getattr(bindings.payments, 'appointments', None) is not bindings.appointments
                or getattr(bindings.payments, 'origin', None) != ORIGIN
                or not all(callable(x) for x in (bindings.authenticate,
                    bindings.auth_app, bindings.release_verifier))
                or (bindings.webhook_app is not None and not callable(bindings.webhook_app))):
            raise DeploymentConfigurationError('Independent runtime bindings required')
        verifier = bindings.release_verifier
        if bindings.transaction_processor is not None and not callable(bindings.transaction_processor):
            raise DeploymentConfigurationError('Trusted transaction processor required')
        customer = create_customer_app(bindings.appointments, bindings.authenticate,
            bindings.payments, bindings.auth_app, ORIGIN, release_verifier=verifier)
    else:
        verifier = _denied
        customer = create_customer_app(None, lambda env: None, None,
            _unavailable, ORIGIN, release_verifier=verifier)

    pipeline = create_pipeline_app(bindings.authenticate if bindings else None,
        bindings.transaction_processor if bindings else None, verifier,
        bindings.transaction_store if bindings else None)
    stream = create_stream_app(bindings.transaction_processor if bindings else None,
        verifier, bindings.transaction_store if bindings else None,
        bindings.stream_verifiers if bindings else None)

    def ready():
        try:
            return verifier() is True
        except Exception:
            return False

    def application(env, start):
        # HTTP_HOST is the actual virtual-host authority. Forwarded headers never
        # extend the allowlist; the TLS frontend must also enforce this boundary.
        host = env.get('HTTP_HOST', '')
        if not isinstance(host, str):
            return _response(start, '421 Misdirected Request', {'error': 'host_denied'})
        host = host.lower()
        path = env.get('PATH_INFO', '')
        if host == 'wsgi-backend:8000' and path == '/api/stream/transactions':
            return stream(env, start)
        if host == 'wsgi-backend:8000' and path in ('/api/auth/verify', '/api/transactions/process'):
            return pipeline(env, start)
        if host.endswith(':443'):
            host = host[:-4]
        if host not in (CANONICAL_HOST, *ALIAS_HOSTS):
            return _response(start, '421 Misdirected Request', {'error': 'host_denied'})
        method, path = env.get('REQUEST_METHOD', ''), env.get('PATH_INFO', '')
        if host != CANONICAL_HOST:
            if method not in ('GET', 'HEAD'):
                return _response(start, '421 Misdirected Request',
                    {'error': 'canonical_origin_required'})
            # Preserve no untrusted request target in a Location header. Users
            # arrive at the canonical platform home and authenticate there.
            start('308 Permanent Redirect', [('Location', ORIGIN + '/'),
                ('Content-Length', '0'), ('Cache-Control', 'no-store')])
            return [b'']
        if path == '/api/platform/free-resources':
            if method != 'GET':
                return _response(start, '405 Method Not Allowed', {'error': 'read_only'}, [('Allow', 'GET')])
            return _response(start, '200 OK', free_resource_catalog())
        if path in ('/healthz', '/readyz'):
            if method != 'GET':
                return _response(start, '405 Method Not Allowed',
                    {'error': 'method_not_allowed'}, [('Allow', 'GET')])
            if path == '/healthz':
                return _response(start, '200 OK',
                    {'platform': 'Sanders Dash & Seal', 'process_alive': True})
            available = ready()
            return _response(start, '200 OK' if available else '503 Service Unavailable',
                {'service_ready': available})
        if path == '/stripe/webhook':
            if bindings is None or bindings.webhook_app is None or not ready():
                return _unavailable(env, start)
            return bindings.webhook_app(env, start)
        if path in ('/api/auth/verify', '/api/transactions/process'):
            return pipeline(env, start)
        if path == '/api/stream/transactions':
            return stream(env, start)
        return customer(env, start)
    return application


def load_application(factory_reference=None, *, transaction_db=None):
    """Load a trusted, administrator-installed adapter factory, not HTTP input.

    Do not set this value from a request or an untrusted configuration file.
    Source/dependency authorization remains the external bootstrap's obligation.
    Invalid explicit configuration fails startup instead of silently downgrading.
    """
    if factory_reference is None:
        return create_application()
    if not isinstance(factory_reference, str) or not FACTORY.fullmatch(factory_reference):
        raise DeploymentConfigurationError('Expected trusted module:factory')
    module, name = factory_reference.split(':')
    factory = getattr(importlib.import_module(module), name)
    if not callable(factory):
        raise DeploymentConfigurationError('Runtime factory must be callable')
    bindings = factory()
    if not isinstance(bindings, RuntimeBindings):
        raise DeploymentConfigurationError('Configured factory must return runtime bindings')
    if (transaction_db is not None and bindings.transaction_processor is not None
            and bindings.transaction_store is None):
        bindings = replace(bindings, transaction_store=TransactionStore(transaction_db))
    return create_application(bindings)

core_platform/free_resources.py.content:
"""Owner-directed OCI free-resource incorporation, without provisioning or spending.

The catalog describes documented allowances. Inventory counts are not billing
meters. This module never adds a deployment gate or grants business authority.
"""
from collections import Counter
from datetime import datetime, timezone
import json
import math
from pathlib import Path


CATALOG = Path(__file__).with_name('oci_free_resources.json')


def catalog():
    value = json.loads(CATALOG.read_text())
    if value.get('platform') != 'Sanders Dash & Seal' or value.get('schema') != 1:
        raise ValueError('Unexpected resource catalog identity')
    return value


def inventory_mapping(report):
    counts = Counter()
    for item in report.get('resources', []):
        if isinstance(item, dict) and isinstance(item.get('resource_type'), str):
            counts[item['resource_type'].casefold()] += 1
    return {'catalog_date': catalog()['catalog_date'],
        'scope': 'PERMISSION_FILTERED_METADATA',
        'scan_complete': report.get('scan_complete') is True,
        'metered_usage_verified': False, 'free_balance_verified': False,
        'cloud_changes_performed': False,
        'resources': [{'id': item['id'], 'related_observations': sum(
            counts[name.casefold()] for name in item['inventory_types']),
            'observation_status': ('RELATED_METADATA_OBSERVED' if any(
                counts[name.casefold()] for name in item['inventory_types']) else 'NOT_OBSERVED'),
            'usage_status': 'NOT_METERED_BY_RESOURCE_SEARCH'} for item in catalog()['resources']]}


def allowance_comparison(resource_id, requested, usage=None, *, account_state='free_only'):
    """Advisory arithmetic over explicit comparable units, never a deployment gate.

    usage must contain every requested metric; absent observation stays unknown.
    Unknown/non-numeric/conditional metrics are rejected instead of treated as zero.
    A comparison is not evidence of actual account eligibility or zero billing.
    """
    entries = {item['id']: item for item in catalog()['resources']}
    if resource_id not in entries or not isinstance(requested, dict) or not requested:
        raise ValueError('Documented resource and named metrics required')
    limits = entries[resource_id]['allowances']
    for key, value in requested.items():
        limit = limits.get(key)
        if (type(value) not in (int, float) or not math.isfinite(value) or value < 0
                or type(limit) not in (int, float) or not math.isfinite(limit)
                or key.startswith(('paid_or_trial_', 'groups_minimum_', 'groups_maximum_'))):
            raise ValueError('Explicit comparable documented metrics required')
    result = {'resource_id': resource_id, 'status': 'USAGE_UNKNOWN',
        'billing_verified': False, 'deployment_authorized': False,
        'cloud_changes_performed': False, 'comparisons': {}}
    if account_state != 'free_only':
        result['status'] = 'ACCOUNT_STATE_REQUIRES_SEPARATE_PROFILE'
        return result
    if not isinstance(usage, dict) or any(key not in usage for key in requested):
        return result
    for key, amount in requested.items():
        used = usage[key]
        if type(used) not in (int, float) or not math.isfinite(used) or used < 0:
            raise ValueError('Explicit nonnegative metered usage required')
        result['comparisons'][key] = {'observed_usage': used, 'requested_addition': amount,
            'projected_usage': used + amount, 'documented_allowance': limits[key],
            'within_documented_amount': used + amount <= limits[key]}
    result['status'] = ('WITHIN_DOCUMENTED_AMOUNTS' if all(
        item['within_documented_amount'] for item in result['comparisons'].values())
        else 'EXCEEDS_DOCUMENTED_AMOUNTS')
    return result


def report():
    return {'generated_at': datetime.now(timezone.utc).isoformat(), 'catalog': catalog(),
            'live_usage': 'NOT_QUERIED', 'cloud_changes_performed': False}


if __name__ == '__main__':
    print(json.dumps(report(), indent=2))

core_platform/hotswap.py.content:
"""L15+ upgrade orchestration primitives: dependency-safe Docker workload cutover.

Development implementation. The deployment adapter must be independently authorized
under the MASTER Twin-Gate/PBD, and must not expose an unrestricted Docker socket.
"""
from dataclasses import dataclass
from hashlib import sha256
import json
import re
from .upgrade_sidecar import require_core_laws

class HotSwapDenied(Exception):
    pass

DIGEST = re.compile(r"^[a-z0-9][a-z0-9._/-]*@sha256:[0-9a-f]{64}$")
IDENT = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")

@dataclass(frozen=True)
class Workload:
    name: str
    role: str
    current_image: str
    candidate_image: str
    dependencies: tuple = ()

    def validate(self):
        if not IDENT.fullmatch(self.name) or self.role not in ("frontend", "backend", "sidecar", "worker"):
            raise HotSwapDenied("Invalid workload identity or role")
        if not DIGEST.fullmatch(self.current_image) or not DIGEST.fullmatch(self.candidate_image):
            raise HotSwapDenied("Only immutable container image digests are permitted")
        if not isinstance(self.dependencies, tuple) or any(not isinstance(x, str) for x in self.dependencies):
            raise HotSwapDenied("Invalid dependency inventory")

@dataclass(frozen=True)
class UpgradePlan:
    release_id: str
    workloads: tuple
    invention_record: dict

    def ordered(self):
        if not IDENT.fullmatch(self.release_id) or not self.workloads:
            raise HotSwapDenied("Invalid release")
        if not isinstance(self.invention_record, dict):
            raise HotSwapDenied("Invention provenance required")
        required = ("inventor", "intended_owner", "confidentiality", "source_commit", "design_reference")
        if any(not isinstance(self.invention_record.get(k), str) or not self.invention_record[k].strip()
               for k in required):
            raise HotSwapDenied("Incomplete patent-protection provenance")
        by_name = {}
        for w in self.workloads:
            w.validate()
            if w.name in by_name:
                raise HotSwapDenied("Duplicate workload")
            by_name[w.name] = w
        ordered, visited, visiting = [], set(), set()
        def visit(name):
            if name not in by_name or name in visiting:
                raise HotSwapDenied("Missing dependency or dependency cycle")
            if name in visited:
                return
            visiting.add(name)
            for dep in by_name[name].dependencies:
                visit(dep)
            visiting.remove(name)
            visited.add(name)
            ordered.append(by_name[name])
        for name in by_name:
            visit(name)
        return tuple(ordered)

    def fingerprint(self):
        ordered = self.ordered()
        payload = {"release_id": self.release_id,
                   "workloads": [dict(name=w.name, role=w.role,
                                      current_image=w.current_image,
                                      candidate_image=w.candidate_image,
                                      dependencies=list(w.dependencies)) for w in ordered],
                   "invention_record": self.invention_record}
        return sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()).hexdigest()

class GovernedHotSwap:
    """Deploy dependency order; health-check, cut over, verify; rollback reverse order.

    All external adapters must be independently verified. This module does not
    mint leases, create signatures, or decide production authority itself.
    """
    def __init__(self, deployment, routing, audit, authorize, core_laws):
        require_core_laws(core_laws)
        self.deployment, self.routing, self.audit, self.authorize = deployment, routing, audit, authorize

    def run(self, plan):
        ordered = plan.ordered()
        fingerprint = plan.fingerprint()
        if self.authorize(plan, fingerprint) is not True:
            raise HotSwapDenied("Independent Twin-Gate/PBD production authorization required")
        started, switched = [], []
        try:
            self.audit.preserve({"stage": "UPGRADE_INTENT", "release": plan.release_id,
                                 "fingerprint": fingerprint, "invention_record": plan.invention_record})
            for w in ordered:
                self.deployment.start_candidate(w)
                started.append(w)
                if self.deployment.healthy(w) is not True:
                    raise HotSwapDenied("Candidate unhealthy: " + w.name)
                self.routing.cutover(w)
                switched.append(w)
                if self.routing.verified(w) is not True:
                    raise HotSwapDenied("Cutover verification failed: " + w.name)
                self.audit.preserve({"stage": "COMPONENT_VERIFIED", "release": plan.release_id,
                                     "component": w.name, "candidate_image": w.candidate_image})
            self.audit.preserve({"stage": "UPGRADE_VERIFIED", "release": plan.release_id,
                                 "fingerprint": fingerprint})
            return "LIVE_VERIFIED"
        except BaseException:
            rollback_errors = []
            for w in reversed(switched):
                try:
                    self.routing.rollback(w)
                except BaseException as exc:
                    rollback_errors.append((w.name, type(exc).__name__))
            for w in reversed(started):
                try:
                    self.deployment.stop_candidate(w)
                except BaseException as exc:
                    rollback_errors.append((w.name, type(exc).__name__))
            self.audit.preserve({"stage": "UPGRADE_SHELTER", "release": plan.release_id,
                                 "rollback_errors": rollback_errors})
            if rollback_errors:
                raise HotSwapDenied("Rollback incomplete; shelter and human intervention required")
            raise

core_platform/identity_continuity.py.content:
"""Shared upgrade continuity guard for platform and independently named RTSAs.

Baselines come from trusted owner configuration. The injected verifier must obtain
independent, artifact-bound candidate evidence; proposal claims are insufficient.
This wrapper preserves the underlying executor's PBD, halt and Twin-Gate checks.
"""
from copy import deepcopy


class IdentityContinuityDenied(ValueError):
    pass


def require_continuity(baseline, candidate):
    if not isinstance(baseline, dict) or not isinstance(candidate, dict):
        raise IdentityContinuityDenied("Identity records required")
    for field in ("identity_id", "role", "authority_boundary"):
        if not baseline.get(field) or candidate.get(field) != baseline[field]:
            raise IdentityContinuityDenied("Identity or authority boundary changed")
    for field in ("capabilities", "protections"):
        old, new = baseline.get(field), candidate.get(field)
        if any(not isinstance(value, list) or not value or
               any(not isinstance(item, str) or not item.strip() for item in value)
               or len(set(value)) != len(value) for value in (old, new)):
            raise IdentityContinuityDenied("Explicit capability/protection inventories required")
        if not set(old).issubset(new):
            raise IdentityContinuityDenied("Historical capability or protection removed")
    return True


class IdentityPreservingExecutor:
    def __init__(self, executor, baselines, candidate_verifier):
        if not isinstance(baselines, dict) or not baselines or not callable(candidate_verifier):
            raise IdentityContinuityDenied("Trusted inventory and verifier required")
        identities = []
        for baseline in baselines.values():
            require_continuity(baseline, baseline)
            identities.append(baseline["identity_id"])
        if len(set(identities)) != len(identities):
            raise IdentityContinuityDenied("Components must retain distinct identities")
        self._baselines = deepcopy(baselines)
        self._executor = executor
        self._verifier = candidate_verifier

    def stage(self, record, artifact_path):
        trusted_record = deepcopy(record)
        baseline = self._baselines.get(trusted_record.get("component"))
        if baseline is None:
            raise IdentityContinuityDenied("Unregistered component")
        candidate = self._verifier(deepcopy(trusted_record), artifact_path)
        require_continuity(baseline, candidate)
        return self._executor.stage(trusted_record, artifact_path)

    def verify(self, record):
        return self._executor.verify(record)

    def rollback(self, record):
        # Recovery remains available, including while an owner halt is active.
        return self._executor.rollback(record)

core_platform/l15_repair_engine.py.content:
"""Sanders Sidecar L15 repair evaluation; simulation only, never execution authority."""
import hashlib
import json
from dataclasses import dataclass

DIMENSIONS = ("causal", "temporal", "counterfactual", "constraint", "systems",
              "adversarial", "probabilistic", "deterministic_verification",
              "multi_hypothesis", "dependency_blast_radius", "security",
              "governance", "self_critique", "state_reconciliation",
              "proof_of_outcome")
PHASES = ("observe", "verify", "diagnose", "simulate", "challenge",
          "authorize", "repair", "reconstruct", "verify_postcondition",
          "commit_or_rollback", "harden", "prove")


class RepairDenied(PermissionError):
    pass


def _digest(data):
    return hashlib.sha256(json.dumps(data, sort_keys=True, separators=(",", ":"),
                                     allow_nan=False).encode()).hexdigest()


def validate_evidence(evidence):
    if not isinstance(evidence, dict) or any(
            not isinstance(evidence.get(k), dict) or not evidence[k] for k in DIMENSIONS):
        raise RepairDenied("All fifteen independent reasoning evidence records are required")
    return _digest({key: evidence[key] for key in DIMENSIONS})


@dataclass(frozen=True)
class RepairProposal:
    incident_id: str
    principal_id: str
    sidecar_id: str
    action: str
    capability: str
    preconditions: tuple
    blast_radius: tuple
    rollback_steps: tuple
    postconditions: tuple
    evidence_digest: str

    def __post_init__(self):
        if not all(isinstance(getattr(self, name), str) and getattr(self, name).strip()
                   for name in ("incident_id", "principal_id", "sidecar_id",
                                "action", "capability", "evidence_digest")):
            raise RepairDenied("Complete repair identity and action required")
        if self.principal_id == self.sidecar_id:
            raise RepairDenied("Sidecar and principal identities must remain distinct")
        if len(self.evidence_digest) != 64 or any(
                c not in "0123456789abcdef" for c in self.evidence_digest):
            raise RepairDenied("Invalid evidence digest")
        for name in ("preconditions", "blast_radius", "rollback_steps", "postconditions"):
            value = getattr(self, name)
            if not isinstance(value, tuple) or not value or any(
                    not isinstance(v, str) or not v.strip() for v in value):
                raise RepairDenied("Preconditions, blast radius, rollback and postconditions required")


class RepairSession:
    """Local hash-chained dry run. Never grants execution or approval."""
    def __init__(self, proposal, evidence):
        if not isinstance(proposal, RepairProposal):
            raise RepairDenied("RepairProposal required")
        if validate_evidence(evidence) != proposal.evidence_digest:
            raise RepairDenied("Evidence mismatch")
        self.proposal = proposal
        self.phase = "observe"
        self.audit = []
        self._prior = "0" * 64
        self._record("created", {"incident": proposal.incident_id})

    def _record(self, kind, details):
        entry = {"prior": self._prior, "kind": kind, "details": details}
        entry["digest"] = _digest(entry)
        self.audit.append(entry)
        self._prior = entry["digest"]

    def advance(self, next_phase, *, independent_review=False):
        current = PHASES.index(self.phase)
        if current + 1 >= len(PHASES) or PHASES[current + 1] != next_phase:
            raise RepairDenied("Out-of-order repair lifecycle transition")
        if next_phase in ("authorize", "repair", "commit_or_rollback"):
            raise RepairDenied("Authorization and execution unavailable in dry-run engine")
        if next_phase in ("challenge", "verify_postcondition", "prove") and independent_review is not True:
            raise RepairDenied("Independent review required")
        self.phase = next_phase
        self._record("phase", {"phase": next_phase})
        return self.phase

    def audit_valid(self):
        prior = "0" * 64
        for entry in self.audit:
            if entry.get("prior") != prior or entry.get("digest") != _digest(
                    {k: v for k, v in entry.items() if k != "digest"}):
                return False
            prior = entry["digest"]
        return True

    def simulation_report(self):
        return {"incident_id": self.proposal.incident_id,
                "principal_id": self.proposal.principal_id,
                "sidecar_id": self.proposal.sidecar_id,
                "action": self.proposal.action,
                "blast_radius": list(self.proposal.blast_radius),
                "rollback_steps": list(self.proposal.rollback_steps),
                "phase": self.phase, "audit_valid": self.audit_valid(),
                "executed": False, "production_authorized": False}

core_platform/lifecycle.py.content:
"""Explicit role boundaries for the Twin-Gate execution lifecycle.

Adapters are trusted host components, not arbitrary uploaded scripts.
No network or shell executor is provided by this development foundation.
"""
from .security import Denied, digest, verify
from .protocol import utc
from .artifacts import DevelopmentArtifactRunner

class QualityAgent:
    def __init__(self, trusted_public_key):
        self.key = trusted_public_key

    def verify_result(self, lease_id, result_bytes, attestation):
        expected = {'lease_id': lease_id, 'result_hash': digest(result_bytes), 'verified': True}
        if attestation.get('body') != expected:
            raise Denied('Quality Agent did not verify this result')
        verify(self.key, attestation.get('signature', ''), 'pbd-quality-v1', expected)

class ITAIManager:
    def __init__(self, trusted_public_key):
        self.key = trusted_public_key

    def reconcile(self, lease_id, result_bytes, attestation):
        expected = {'lease_id': lease_id, 'result_hash': digest(result_bytes), 'reconciled': True}
        if attestation.get('body') != expected:
            raise Denied('IT AI Manager did not reconcile this operation')
        verify(self.key, attestation.get('signature', ''), 'pbd-reconcile-v1', expected)

class Minotaur:
    def __init__(self, trusted_public_key):
        self.key = trusted_public_key

    def reseal(self, lease_id, result_bytes, attestation):
        expected = {'lease_id': lease_id, 'result_hash': digest(result_bytes), 'integrity_confirmed': True}
        if attestation.get('body') != expected:
            raise Denied('MINOTAUR did not confirm integrity')
        verify(self.key, attestation.get('signature', ''), 'pbd-integrity-v1', expected)

class LabyrinthShield:
    """Separate in-process containment state; OS isolation remains an adapter duty."""
    def __init__(self):
        self.quarantined = set()
        self.mode = 'GOVERNED'

    def contain(self, agent_key):
        self.quarantined.add(agent_key)
        self.mode = 'HUMANITARIAN'

    def check(self, agent_key):
        if self.mode != 'GOVERNED' or agent_key in self.quarantined:
            raise Denied('Shelter in place; human clearance required')

class GovernedLifecycle:
    def __init__(self, vault, validator, quality, manager, minotaur, shield, audit):
        if len({quality.key, manager.key, minotaur.key}) != 3:
            raise ValueError('Independent verification requires three distinct keys')
        if (manager.key != vault.gate.keys['IT_AI_Manager_v15.0'] or
                minotaur.key != vault.gate.keys['MINOTAUR']):
            raise ValueError('Authority keys must match the Vault trust configuration')
        self.vault, self.validator, self.audit = vault, validator, audit
        self.quality, self.manager, self.minotaur, self.shield = quality, manager, minotaur, shield

    def run(self, lease_id, scope, payload, proof, artifact, runner,
            quality_check, reconcile_check, integrity_check):
        body = None
        result = None
        status = 'DENIED'
        receipt = None
        execution_receipt = None
        started = utc(self.vault.clock())
        try:
            # Consumed authority can never be reused, including after process failure.
            body = self.vault.claim(lease_id, scope, payload, proof)
            self.shield.check(body['execution_binding']['agent_public_key'])
            if type(runner) is not DevelopmentArtifactRunner or runner.validator is not self.validator:
                raise Denied('Unapproved execution runner')
            runner.validate(artifact, scope)
            if digest(artifact.source) != body['execution_binding']['artifact_hash']:
                raise Denied('Executable differs from the lease-bound artifact')
            # Persist intent before any side effect. Audit failure prevents adapter entry.
            self.audit.preserve({'lease_id': lease_id, 'stage': 'EXECUTION_INTENT',
                                 'artifact': artifact.name, 'artifact_hash': digest(artifact.source), 'payload_hash': digest(payload)})
            result = runner.execute(artifact, scope, payload)
            if not isinstance(result, bytes):
                raise Denied('Adapter result must be bytes')
            quality = quality_check(lease_id, result)
            self.quality.verify_result(lease_id, result, quality)
            reconciliation = reconcile_check(lease_id, result)
            self.manager.reconcile(lease_id, result, reconciliation)
            integrity = integrity_check(lease_id, result)
            self.minotaur.reseal(lease_id, result, integrity)
            receipt = {'quality': quality, 'reconciliation': reconciliation, 'integrity': integrity}
            status = 'VERIFIED'
        except BaseException:
            if body:
                self.shield.contain(body['execution_binding']['agent_public_key'])
            raise
        finally:
            # Authority was already consumed. Revoke even when evidence preservation fails.
            try:
                try:
                    execution_receipt = {
                        'execution_metadata': {'lease_id': lease_id,
                            'executed_by': body['agent_identity']['requesting_agent'] if body else None,
                            'started_at_utc': started, 'completed_at_utc': utc(self.vault.clock())},
                        'functional_telemetry': {'http_status_returned': None,
                            'payload_bytes_transferred': None, 'execution_result': status,
                            'post_condition_verified': status == 'VERIFIED'},
                        'post_execution_clearance': {
                            'quality_agent_synthetic_validation': receipt['quality'] if receipt else None,
                            'it_manager_state_reconciliation': receipt['reconciliation'] if receipt else None,
                            'minotaur_integrity_seal': receipt['integrity'] if receipt else None}}
                    execution_receipt = self.audit.preserve_execution(execution_receipt)
                finally:
                    self.vault.revoke(lease_id)
                self.audit.preserve({'lease_id': lease_id, 'stage': 'AUTHORITY_REVOKED'})
            except BaseException:
                # Evidence and authority cleanup are required parts of completion.
                if body:
                    self.shield.contain(body['execution_binding']['agent_public_key'])
                raise
        return {'lease_id': lease_id, 'status': status, 'authority': 'REVOKED',
                'execution_receipt': execution_receipt}

core_platform/local_upgrade_executor.py.content:
"""Local atomic artifact staging adapter for the Sanders Dash & Seal sidecar.

This is a filesystem staging executor, NOT a production process manager or
an independent authorization, AI inference, or OS sandbox service.
"""
import hashlib
import json
import os
from pathlib import Path
import shutil
import tempfile


class LocalUpgradeExecutor:
    def __init__(self, root):
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def _component_dir(self, record):
        name = record["component"]
        if not isinstance(name, str) or not name or not all(
            c.isascii() and (c.isalnum() or c in "_-") for c in name
        ):
            raise ValueError("Invalid component")
        directory = self.root / name
        directory.mkdir(parents=True, exist_ok=True)
        return directory

    def _state(self, directory):
        state = directory / "state.json"
        if not state.exists():
            return {}
        return json.loads(state.read_text(encoding="utf-8"))

    def _write_state(self, directory, state):
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".state-")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(state, stream, sort_keys=True)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(tmp, directory / "state.json")
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)

    def stage(self, record, artifact_path):
        directory = self._component_dir(record)
        if self._state(directory).get("pending"):
            raise ValueError("Unverified upgrade already staged")
        source = Path(artifact_path)
        if not source.is_file() or source.is_symlink():
            raise ValueError("Regular source required")
        payload = source.read_bytes()
        actual = hashlib.sha256(payload).hexdigest()
        if actual != record["artifact_hash"]:
            raise ValueError("Artifact digest mismatch")
        current = directory / "current.bin"
        previous = directory / "previous.bin"
        if current.exists():
            shutil.copyfile(current, previous)
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".artifact-")
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(payload)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(tmp, current)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)
        self._write_state(directory, {
            "pending": True, "digest": actual,
            "previous": previous.exists(), "version": record["version"]
        })
        return {"staged": True, "sha256": actual, "mode": "local-dark"}

    def verify(self, record):
        directory = self._component_dir(record)
        state = self._state(directory)
        current = directory / "current.bin"
        if not state.get("pending") or not current.exists():
            return {"healthy": False}
        digest = hashlib.sha256(current.read_bytes()).hexdigest()
        if digest != record["artifact_hash"] or digest != state.get("digest"):
            return {"healthy": False}
        state["pending"] = False
        self._write_state(directory, state)
        return {"healthy": True, "sha256": digest, "scope": "artifact-integrity-only"}

    def rollback(self, record):
        directory = self._component_dir(record)
        state = self._state(directory)
        previous = directory / "previous.bin"
        current = directory / "current.bin"
        if not state.get("previous") or not previous.exists():
            return {"restored": False, "reason": "no prior baseline"}
        os.replace(previous, current)
        state["pending"] = False
        state["digest"] = hashlib.sha256(current.read_bytes()).hexdigest()
        state["previous"] = False
        self._write_state(directory, state)
        return {"restored": True, "sha256": state["digest"]}

core_platform/native_runtime.py.content:
"""Concrete server composition for customer intake, payments and ingestion.

Customer accounts prove account access, never commission, signer identity or
independent AI authority. Those authorities remain separate from this runtime.
"""
import hashlib
import io
import json
import os
import re
from pathlib import Path
import sqlite3

from .provider_connections import WriteProviderClient
from .provider_workflows import ProviderWorkflows, ProviderUnavailable, ProviderRequestConflict
from .cases import CaseDenied
from .accounts import AccountStore, auth_app
from .appointments import AppointmentStore
from .appointment_payments import AppointmentPayments
from .cases import CaseRegistry
from .deployment import RuntimeBindings, create_application, ORIGIN, _response
from .glass_box_audit import GlassBoxAudit
from .pipeline_api import TransactionStore, TransactionRejected, create_pipeline_app
from .stripe_payments import PaymentLedger, PaymentDenied
from .stripe_webhook_wsgi import make_app
from .stream_api import strict_json
from .upgrade_sidecar import CORE_LAWS


class UnconfiguredStripeClient:
    def __getattr__(self,name):raise PaymentDenied('Stripe credentials unavailable')


def read_settings(path):
    path=Path(path)
    if not path.exists():return {}
    info=path.stat()
    if path.is_symlink() or info.st_uid!=0 or info.st_mode & 0o037 or info.st_size>16384:
        raise ValueError('Runtime secret configuration must be root-owned, private and bounded')
    settings=json.loads(path.read_text())
    if not isinstance(settings,dict) or set(settings)-{
        'owner_setup_digest','owner_setup_expires','stripe_api_key','stripe_webhook_secret','stripe_livemode',
        'signwell_api_key','signwell_test_mode','bluenotary_api_key'}:
        raise ValueError('Invalid runtime configuration fields')
    return settings


class NativeRuntime:
    def __init__(self,path,settings=None,*,stripe_client=None):
        self.path=str(path);Path(path).parent.mkdir(parents=True,exist_ok=True)
        os.umask(0o077)
        os.chmod(Path(path).parent,0o700)
        settings={} if settings is None else settings
        self.accounts=AccountStore(path,setup_digest=settings.get('owner_setup_digest'),
            setup_expires=settings.get('owner_setup_expires',0))
        self.audit=GlassBoxAudit(Path(path).with_name('sds_audit.db'))
        self.cases=CaseRegistry(path,CORE_LAWS)
        self.appointments=AppointmentStore(self.cases,self.audit)
        self.ledger=PaymentLedger(path)
        self.store=TransactionStore(path)
        with self.store.connect() as db:
            db.execute('''CREATE TABLE IF NOT EXISTS sds_ingestion_events (
                actor TEXT NOT NULL, request_id TEXT NOT NULL, payload TEXT NOT NULL,
                sha256_digest TEXT NOT NULL, status TEXT NOT NULL,
                PRIMARY KEY(actor,request_id))''')
        livemode=settings.get('stripe_livemode',True)
        if type(livemode) is not bool:raise ValueError('Explicit Stripe environment must be boolean')
        key=settings.get('stripe_api_key')
        secret=settings.get('stripe_webhook_secret')
        if key:
            prefix=('rk_live_','sk_live_') if livemode else ('rk_test_','sk_test_')
            if not isinstance(key,str) or not key.startswith(prefix):
                raise ValueError('Stripe key must match configured environment')
        if secret and (not isinstance(secret,str) or not secret.startswith('whsec_')):
            raise ValueError('Invalid Stripe webhook secret configuration')
        if key and secret and stripe_client is None:
            from stripe import StripeClient
            stripe_client=StripeClient(key,stripe_version='2026-08-26.dahlia',max_network_retries=2)
        if type(settings.get('signwell_test_mode',False)) is not bool:
            raise ValueError('Explicit SignWell environment must be boolean')
        clients={}
        for provider in ('signwell','bluenotary'):
            if settings.get(provider+'_api_key'):
                clients[provider]=WriteProviderClient(provider,settings[provider+'_api_key'])
        self.providers=ProviderWorkflows(path,self.cases,self.accounts.operator,self.audit,clients,
            signwell_test_mode=settings.get('signwell_test_mode',False))
        self.payments_configured=bool(key and secret)
        # A test-supplied client never changes whether production credentials exist.
        client=stripe_client or UnconfiguredStripeClient()
        self.payments=AppointmentPayments(self.appointments,self.ledger,client,
            self.accounts.operator,self.fee_review,self.checkout_eligibility,self.audit,ORIGIN,
            expected_livemode=livemode)
        self.webhook=make_app(self.ledger,secret,enabled=bool(secret),expected_livemode=livemode)
        self.bindings=RuntimeBindings(self.appointments,self.payments,self.accounts.authenticate,
            auth_app(self.accounts,ORIGIN),self.available,self.webhook,self.process_event,self.store)
        self.base=create_application(self.bindings)
        self.pipeline=create_pipeline_app(self.accounts.authenticate,self.process_event,self.available,self.store)

    def available(self):
        # Core service readiness is not permission to perform a privileged AI/notarial operation.
        try:
            self.audit.verify_audit()
            with self.store.connect() as db:
                return db.execute('PRAGMA quick_check').fetchone()[0]=='ok'
        except Exception:
            return False

    def fee_review(self,case,actor,items):
        # The authenticated operator's itemized approval is a human decision,
        # not an automated certification of statutory fee or commission compliance.
        if not self.accounts.operator(actor):return False
        self.audit.preserve({'stage':'HUMAN_ITEMIZED_QUOTE_REVIEW', 'case_id':case['case_id'],
                            'actor':actor,'items_sha256':hashlib.sha256(json.dumps(items,sort_keys=True).encode()).hexdigest()})
        return True

    def checkout_eligibility(self,appointment,requester):
        self.appointments.get(appointment['case_id'],requester)
        with self.appointments.connect() as db:
            row=db.execute('SELECT 1 FROM appointment_quotes WHERE case_id=?',(appointment['case_id'],)).fetchone()
        return bool(row)

    def process_event(self,transaction,actor,db):
        if (set(transaction)!={'request_id','action','payload'} or transaction['action']!='dispatch_transaction'
            or not isinstance(transaction['payload'],dict)):
            raise TransactionRejected('Only authenticated ingestion is available through this transport')
        raw=json.dumps(transaction['payload'],sort_keys=True,separators=(',',':'),allow_nan=False)
        if len(raw.encode())>65536:raise TransactionRejected('Payload too large')
        checksum=hashlib.sha256(raw.encode()).hexdigest()
        db.execute('INSERT INTO sds_ingestion_events VALUES (?,?,?,?,?)',
                   (actor,transaction['request_id'],raw,checksum,'RECEIVED'))
        return {'status':'RECEIVED','sha256_digest':checksum,'notarial_act_executed':False}

    def status(self):
        return {'platform':'Sanders Dash & Seal','accounts':True,'appointment_intake':True,
            'operator_quotes':True,'durable_ingestion':True,'stripe_credentials_configured':self.payments_configured,
            'signwell_credentials_configured':'signwell' in self.providers.clients,
            'bluenotary_credentials_configured':'bluenotary' in self.providers.clients,
            'provider_request_workflows_implemented':True,'live_payment_verified':False,'notarial_execution_connected':False,
            'independent_ai_authorities_connected':False,'complete_build_verified':False}

    def __call__(self,env,start):
        path=env.get('PATH_INFO','');host=env.get('HTTP_HOST','')
        if host not in ('sandersdashandseal.com','sandersdashandseal.com:443'):
            return self.base(env,start)
        provider_route=re.fullmatch(r'/api/operator/appointments/([A-Za-z0-9_.-]{1,128})/providers(?:/(signwell|bluenotary))?',path)
        if provider_route:
            actor=self.accounts.authenticate(env)
            if actor is None:return _response(start,'401 Unauthorized',{'error':'sign_in_required'})
            if not self.accounts.operator(actor):return _response(start,'403 Forbidden',{'error':'operator_required'})
            case_id,provider=provider_route.groups()
            try:
                if provider is None and env.get('REQUEST_METHOD')=='GET':
                    return _response(start,'200 OK',{'requests':self.providers.records(case_id,actor)})
                if provider is None or env.get('REQUEST_METHOD')!='POST':
                    return _response(start,'405 Method Not Allowed',{'error':'method_not_allowed'})
                if env.get('HTTP_ORIGIN')!=ORIGIN:
                    return _response(start,'403 Forbidden',{'error':'origin_denied'})
                if env.get('CONTENT_TYPE','').split(';')[0].strip()!='application/json':
                    return _response(start,'415 Unsupported Media Type',{'error':'json_required'})
                n=int(env.get('CONTENT_LENGTH','0'))
                if not 0<n<=32768:raise ValueError('Invalid body length')
                raw=env['wsgi.input'].read(n)
                if len(raw)!=n:raise ValueError('Incomplete body')
                result=self.providers.submit(case_id,actor,provider,strict_json(raw))
                return _response(start,'201 Created',result)
            except PermissionError:
                return _response(start,'403 Forbidden',{'error':'operator_required'})
            except CaseDenied:
                return _response(start,'404 Not Found',{'error':'case_not_found'})
            except ProviderRequestConflict:
                return _response(start,'409 Conflict',{'error':'request_conflict_or_outcome_unknown'})
            except ProviderUnavailable:
                return _response(start,'503 Service Unavailable',{'error':'provider_unavailable',
                    'detail':'Check provider configuration or the existing request outcome before resubmitting.'})
            except (ValueError,TypeError,KeyError,UnicodeError,RecursionError):
                return _response(start,'400 Bad Request',{'error':'invalid_request'})
        if path=='/api/platform/status':
            if env.get('REQUEST_METHOD')!='GET':return _response(start,'405 Method Not Allowed',{'error':'read_only'})
            return _response(start,'200 OK',self.status())
        if path=='/readyz' and env.get('REQUEST_METHOD')=='GET':
            ready=self.available()
            return _response(start,'200 OK' if ready else '503 Service Unavailable',
                {'service_ready':ready,'complete_build_ready':False,'capabilities':self.status()})
        if path=='/api/pipeline/events':
            if env.get('REQUEST_METHOD')!='POST':return _response(start,'405 Method Not Allowed',{'error':'post_required'})
            if self.accounts.authenticate(env) is None:return _response(start,'401 Unauthorized',{'error':'sign_in_required'})
            if 'HTTP_AUTHORIZATION' not in env and env.get('HTTP_ORIGIN')!=ORIGIN:
                return _response(start,'403 Forbidden',{'error':'origin_denied'})
            if env.get('CONTENT_TYPE','').split(';')[0]!='application/json':
                return _response(start,'415 Unsupported Media Type',{'error':'json_required'})
            try:
                n=int(env.get('CONTENT_LENGTH','0'))
                if not 0<n<=70000:raise ValueError()
                raw=env['wsgi.input'].read(n)
                if len(raw)!=n:raise ValueError()
                transaction=strict_json(raw)
                data=json.dumps({'transaction':transaction,'session':{
                    'authorization':'Bearer '+self.accounts.credential(env)}}).encode()
            except (ValueError,TypeError,KeyError,UnicodeError,RecursionError):
                return _response(start,'400 Bad Request',{'error':'invalid_request'})
            internal=dict(env,PATH_INFO='/api/transactions/process',CONTENT_LENGTH=str(len(data)),
                          **{'wsgi.input':io.BytesIO(data)})
            return self.pipeline(internal,start)
        return self.base(env,start)


def create_native_application(path=None,*,config_path=None,settings=None,stripe_client=None):
    path=path or os.environ.get('SQLITE_DB_PATH','/app/data/sds_production.db')
    if settings is None:
        settings=read_settings(config_path or '/run/sds/runtime.json')
    return NativeRuntime(path,settings,stripe_client=stripe_client)

core_platform/pipeline_api.py.content:
"""Python authority and durable receipts for the owner-selected Node transport.

Connecting code: adapters are independent production authority, not identities
claimed by Node. A processor validates its operation and writes business state
using the supplied SQLite connection. No generic payload grants notarial power.
"""
import hashlib
import json
from pathlib import Path
import re
import sqlite3
import time
import uuid


IDENT = re.compile(r'[A-Za-z0-9_.-]{1,128}', re.ASCII)


class TransactionRejected(ValueError):
    pass


class TransactionStore:
    def __init__(self, path):
        self.path = str(path)
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with self.connect() as db:
            db.execute('''CREATE TABLE IF NOT EXISTS pipeline_receipts (
                actor TEXT NOT NULL, request_id TEXT NOT NULL,
                fingerprint TEXT NOT NULL, receipt TEXT NOT NULL,
                PRIMARY KEY(actor, request_id))''')

    def connect(self):
        db = sqlite3.connect(self.path, timeout=5)
        db.execute('PRAGMA foreign_keys=ON')
        return db

    def process(self, transaction, actor, processor):
        if (not isinstance(transaction, dict)
                or not isinstance(transaction.get('request_id'), str)
                or not IDENT.fullmatch(transaction['request_id'])):
            raise TransactionRejected('request_id required')
        canonical = json.dumps(transaction, sort_keys=True, separators=(',', ':'), allow_nan=False)
        fingerprint = hashlib.sha256(canonical.encode()).hexdigest()
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            previous = db.execute('SELECT fingerprint,receipt FROM pipeline_receipts '
                'WHERE actor=? AND request_id=?', (actor, transaction['request_id'])).fetchone()
            if previous:
                if previous[0] != fingerprint:
                    raise TransactionRejected('Conflicting request reuse')
                return json.loads(previous[1])
            # Business validation, human authority and auditing remain obligations
            # of the trusted processor. External irreversible effects require an
            # outbox/idempotent dispatcher, not a network call inside this commit.
            result = processor(transaction, actor, db)
            if not isinstance(result, dict):
                raise TransactionRejected('Processor must provide a validated result')
            receipt = {'receipt_id': uuid.uuid4().hex,
                'request_id': transaction['request_id'], 'recorded_at': int(time.time()),
                'result': result}
            encoded = json.dumps(receipt, separators=(',', ':'), allow_nan=False)
            if len(encoded.encode()) > 65536:
                raise TransactionRejected('Receipt too large')
            db.execute('INSERT INTO pipeline_receipts VALUES (?,?,?,?)',
                (actor, transaction['request_id'], fingerprint, encoded))
        return receipt


def create_pipeline_app(authenticate=None, processor=None, release_verifier=None, store=None):
    def app(env, start):
        def respond(status, payload):
            raw = json.dumps(payload, separators=(',', ':')).encode()
            start(status, [('Content-Type', 'application/json'),
                ('Content-Length', str(len(raw))), ('Cache-Control', 'no-store')])
            return [raw]
        try:
            ready = (callable(authenticate) and callable(release_verifier)
                     and release_verifier() is True)
        except Exception:
            ready = False
        if not ready:
            return respond('503 Service Unavailable', {'error': 'authority_unavailable'})
        if env.get('REQUEST_METHOD') != 'POST':
            return respond('405 Method Not Allowed', {'error': 'post_required'})
        path = env.get('PATH_INFO')
        if path not in ('/api/auth/verify', '/api/transactions/process'):
            return respond('404 Not Found', {'error': 'not_found'})
        data = None
        authorization = env.get('HTTP_AUTHORIZATION')
        if path == '/api/transactions/process':
            if processor is None or store is None:
                return respond('503 Service Unavailable', {'error': 'processor_unavailable'})
            if env.get('CONTENT_TYPE', '').split(';')[0].strip() != 'application/json':
                return respond('415 Unsupported Media Type', {'error': 'json_required'})
            try:
                length = int(env.get('CONTENT_LENGTH', '0'))
                if not 0 < length <= 1048576:
                    raise ValueError('length')
                raw = env['wsgi.input'].read(length)
                if len(raw) != length:
                    raise ValueError('short body')
                def invalid_constant(value):
                    raise ValueError('Nonfinite JSON')
                data = json.loads(raw, parse_constant=invalid_constant)
                if not isinstance(data, dict) or set(data) != {'transaction', 'session'}:
                    raise ValueError('envelope')
                session = data['session']
                if not isinstance(session, dict) or set(session) != {'authorization'}:
                    raise ValueError('session')
                authorization = session['authorization']
            except (ValueError, TypeError, KeyError, UnicodeError):
                return respond('400 Bad Request', {'error': 'invalid_request'})
        if (not isinstance(authorization, str) or not 1 <= len(authorization) <= 4096
                or any(ord(c) < 32 or ord(c) > 126 for c in authorization)):
            return respond('401 Unauthorized', {'error': 'session_unavailable'})
        # Reconstruct credentials only, never accept a forwarded actor/role.
        authentication_env = dict(env, HTTP_AUTHORIZATION=authorization)
        for key in ('HTTP_COOKIE', 'HTTP_X_USER', 'HTTP_X_ROLE', 'HTTP_X_FORWARDED_USER'):
            authentication_env.pop(key, None)
        try:
            actor = authenticate(authentication_env)
        except Exception:
            actor = None
        if not isinstance(actor, str) or not IDENT.fullmatch(actor):
            return respond('401 Unauthorized', {'error': 'session_unavailable'})
        if path == '/api/auth/verify':
            # Internal response to Node only; no invented session issuer. Every
            # submission revalidates the original credential independently.
            return respond('200 OK', {'authorization': authorization})
        try:
            receipt = store.process(data['transaction'], actor, processor)
            return respond('200 OK', receipt)
        except (TransactionRejected, ValueError, TypeError):
            return respond('422 Unprocessable Entity', {'error': 'transaction_rejected'})
        except Exception:
            return respond('503 Service Unavailable', {'error': 'transaction_unavailable'})
    return app

core_platform/platform_integration.py.content:
"""MASTER-governed integration boundary for Sanders Dash & Seal.

Connects existing intake, human authority review, technical dispatch and upgrade
sidecar without merging their authority domains. No execution or deployment is
implied by a successful orchestration result.
"""
from .upgrade_sidecar import require_core_laws


class IntegrationDenied(Exception):
    pass


class SandersDashSealIntegration:
    """Fail-closed composition of independently governed existing components."""

    PLATFORM = 'Sanders Dash & Seal'

    def __init__(self, cases, authority, dispatcher, sidecar, audit, core_laws):
        require_core_laws(core_laws)
        components = (cases, authority, dispatcher, sidecar, audit)
        if any(component is None for component in components):
            raise IntegrationDenied('All five independent components are required')
        if len({id(component) for component in components}) != len(components):
            raise IntegrationDenied('Independent roles cannot be merged')
        if authority.cases is not cases:
            raise IntegrationDenied('Authority review must use the same case registry')
        if dispatcher.audit is not audit or authority.audit is not audit:
            raise IntegrationDenied('Shared glass-box evidence boundary required')
        self.cases = cases
        self.authority = authority
        self.dispatcher = dispatcher
        self.sidecar = sidecar
        self.audit = audit

    def intake(self, case_id, jurisdiction, service, requester):
        self.audit.preserve({'stage': 'CASE_INTAKE_INTENT', 'case_id': case_id,
                             'platform': self.PLATFORM})
        result = self.cases.create(case_id, jurisdiction, service, requester)
        self.audit.preserve({'stage': 'CASE_AWAITING_HUMAN_REVIEW',
                             'case_id': case_id, 'status': result['status']})
        return result

    def human_review(self, case_id, reviewer, notary_identity, evidence):
        result = self.authority.review(case_id, reviewer, notary_identity, evidence)
        if result.get('notarial_act_executed') is not False:
            raise IntegrationDenied('Review cannot imply a notarial act')
        return result

    def request_technical_work(self, task_id, role, capability, component,
                               specification_ref, evidence):
        if not specification_ref.startswith('MASTER '):
            raise IntegrationDenied('Technical work must reference MASTER')
        return self.dispatcher.submit(task_id, role, capability, component,
                                      specification_ref, evidence)

    def propose_upgrade(self, request_id, component, version, artifact_hash, evidence):
        if not isinstance(evidence, dict) or not evidence.get('master_section'):
            raise IntegrationDenied('MASTER section traceability required')
        self.audit.preserve({'stage': 'UPGRADE_INTENT', 'request_id': request_id,
                             'component': component,
                             'master_section': evidence['master_section']})
        return self.sidecar.propose(request_id, component, version, artifact_hash, evidence)

    def execute_notarial_act(self, *args, **kwargs):
        raise IntegrationDenied('Independent live provider and jurisdiction authority required')

    def deploy(self, *args, **kwargs):
        raise IntegrationDenied('Signed PBD, Twin-Gate, Vault and production runtime required')

core_platform/protocol.py.content:
"""MASTER section 9 field structure and canonical signing material.

The signed execution binding supplies the concrete bytes/key/operation referenced
by the MASTER's symbolic signature expressions. It is not a substitute schema.
"""
import copy
import ipaddress
import re
from datetime import datetime, timezone
from .security import Denied, digest

GATES = ('it_manager_operational_necessity_signoff',
         'minotaur_labyrinth_shield_clearance_hash')


def utc(timestamp):
    return datetime.fromtimestamp(timestamp, timezone.utc).isoformat(timespec='microseconds').replace('+00:00', 'Z')


def timestamp(value):
    try:
        if not isinstance(value, str) or not value.endswith('Z'):
            raise ValueError()
        return datetime.fromisoformat(value[:-1] + '+00:00').timestamp()
    except (ValueError, TypeError, OverflowError) as exc:
        raise Denied('UTC timestamp required') from exc


def signing_material(record):
    value = copy.deepcopy(record)
    value['agent_identity']['agent_identity_assertion'] = ''
    value['dual_governance_gates'] = {name: '' for name in GATES}
    return value


def assert_record(record, max_lifetime, now):
    try:
        if set(record) != {'lease_metadata', 'agent_identity', 'operational_bounds',
                           'dual_governance_gates', 'execution_binding'}:
            raise ValueError()
        meta, agent, bounds = (record[k] for k in ('lease_metadata', 'agent_identity', 'operational_bounds'))
        binding = record['execution_binding']
        if set(meta) != {'lease_id', 'timestamp_utc', 'expires_at_utc', 'nonce'}:
            raise ValueError()
        if set(agent) != {'requesting_agent', 'agent_identity_assertion', 'commanding_authority'}:
            raise ValueError()
        if set(bounds) != {'target_endpoint', 'allowed_verbs', 'network_jail_ips', 'max_execution_limit'}:
            raise ValueError()
        if set(binding) != {'agent_public_key', 'payload_hash', 'operation', 'token_class', 'artifact_hash'}:
            raise ValueError()
        if set(record['dual_governance_gates']) != set(GATES):
            raise ValueError()
        if agent['commanding_authority'] != 'IT_AI_Manager_v15.0':
            raise ValueError()
        for value in (meta['lease_id'], meta['nonce'], agent['requesting_agent'],
                      bounds['target_endpoint'], binding['operation']):
            if not isinstance(value, str) or not value or '*' in value:
                raise ValueError()
        if not all(re.fullmatch('[0-9a-f]{64}', binding[k]) for k in ('payload_hash', 'artifact_hash')):
            raise ValueError()
        if not re.fullmatch('[0-9a-f]{64}', binding['agent_public_key']):
            raise ValueError()
        for field in ('allowed_verbs', 'network_jail_ips'):
            values = bounds[field]
            if not isinstance(values, list) or not values or not all(isinstance(v, str) for v in values):
                raise ValueError()
            if len(values) != len(set(values)):
                raise ValueError()
        if any(v not in ('GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS') for v in bounds['allowed_verbs']):
            raise ValueError()
        for ip in bounds['network_jail_ips']:
            ipaddress.ip_address(ip)
        if type(bounds['max_execution_limit']) is not int or bounds['max_execution_limit'] != 1:
            raise ValueError()
        issued, expires = timestamp(meta['timestamp_utc']), timestamp(meta['expires_at_utc'])
        limit = max_lifetime[binding['token_class']]
        if not issued <= now < expires or not 0 < expires - issued <= limit:
            raise ValueError()
    except (KeyError, ValueError, TypeError, OverflowError) as exc:
        raise Denied('Invalid lease structure, scope, or lifetime policy') from exc


def check_operation(record, scope, payload):
    bounds, binding = record['operational_bounds'], record['execution_binding']
    if (set(scope) != {'endpoint', 'method', 'ip', 'operation'}
        or scope['endpoint'] != bounds['target_endpoint']
        or scope['method'] not in bounds['allowed_verbs']
        or scope['ip'] not in bounds['network_jail_ips']
        or scope['operation'] != binding['operation']
        or digest(payload) != binding['payload_hash']):
        raise Denied('Operation outside signed scope')

core_platform/provider_connections.py.content:
"""Provider API connections for Sanders Dash & Seal.

Secrets must be injected by the deployment secret manager; never log tokens.
WriteProviderClient adds the documented document/session creation operations.
"""
import json
import urllib.error
import urllib.parse
import urllib.request


class ProviderConnectionError(RuntimeError):
    pass


class ReadOnlyProviderClient:
    def __init__(self, provider, api_key, *, timeout=10, opener=None):
        if provider not in ('signwell', 'bluenotary'):
            raise ValueError('unsupported provider')
        if (not isinstance(api_key, str) or not 8 <= len(api_key) <= 4096
                or any(ord(c) < 33 or ord(c) > 126 for c in api_key)):
            raise ValueError('API credential required')
        if not 1 <= timeout <= 30:
            raise ValueError('timeout outside allowed range')
        self.provider = provider
        self._api_key = api_key
        self.timeout = timeout
        self._opener = opener or urllib.request.build_opener(NoRedirect()).open

    def _get(self, url):
        header = ('X-Api-Key', self._api_key) if self.provider == 'signwell' else ('Authorization', 'Bearer ' + self._api_key)
        req = urllib.request.Request(url, headers={header[0]: header[1], 'Accept': 'application/json'}, method='GET')
        try:
            with self._opener(req, timeout=self.timeout) as response:
                raw = response.read(1024 * 1024 + 1)
                if len(raw) > 1024 * 1024:
                    raise ValueError('Provider response too large')
                return json.loads(raw)
        except (urllib.error.HTTPError, urllib.error.URLError, ValueError, OSError) as exc:
            # Do not expose response bodies, URL query parameters, or credentials.
            raise ProviderConnectionError(self.provider + ' read-only request failed') from None

    def get_document(self, document_id):
        if self.provider != 'signwell':
            raise ValueError('SignWell operation only')
        return self._get('https://www.signwell.com/api/v1/documents/' + _safe_id(document_id))

    def get_session(self, session_id):
        if self.provider != 'bluenotary':
            raise ValueError('BlueNotary operation only')
        return self._get('https://app.bluenotary.us/api/integrationsv2/sessions/' + _safe_id(session_id))


def _safe_id(value):
    if not isinstance(value, str) or not value or len(value) > 128:
        raise ValueError('invalid resource identifier')
    if not all(c.isascii() and (c.isalnum() or c in '-_') for c in value):
        raise ValueError('invalid resource identifier')
    return urllib.parse.quote(value, safe='')


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        # Never forward an API credential to a redirected host.
        return None


class WriteProviderClient(ReadOnlyProviderClient):
    def create_request(self, payload):
        url = ('https://www.signwell.com/api/v1/document_templates/documents/' if self.provider == 'signwell'
               else 'https://app.bluenotary.us/api/integrationsv2/sessions/')
        header = ('X-Api-Key', self._api_key) if self.provider == 'signwell' else ('Authorization', 'Bearer ' + self._api_key)
        req = urllib.request.Request(url, data=json.dumps(payload, allow_nan=False).encode(),
            headers={header[0]: header[1], 'Content-Type': 'application/json', 'Accept': 'application/json'}, method='POST')
        try:
            with self._opener(req, timeout=self.timeout) as response:
                raw = response.read(1024 * 1024 + 1)
                if len(raw) > 1024 * 1024:
                    raise ValueError('Provider response too large')
                result = json.loads(raw)
                if not isinstance(result, dict):
                    raise ValueError('Provider object required')
                return result
        except (urllib.error.HTTPError, urllib.error.URLError, ValueError, OSError):
            raise ProviderConnectionError(self.provider + ' request outcome unavailable') from None

core_platform/provider_workflows.py.content:
"""Human-directed, case-bound provider requests; never a notarial execution grant.

Only fingerprints and provider references are persisted. An uncertain POST is
never retried automatically: neither provider documents an idempotency guarantee.
"""
import hashlib
import json
import re
import sqlite3
import time
from datetime import datetime
from .provider_connections import ProviderConnectionError


class ProviderUnavailable(Exception):
    pass


class ProviderRequestConflict(Exception):
    pass


def text(value, maximum=160):
    if (not isinstance(value, str) or not 1 <= len(value) <= maximum
            or value != value.strip() or any(ord(c) < 32 for c in value)):
        raise ValueError('Invalid provider request field')
    return value


def identifier(value):
    value = text(value, 128)
    if not re.fullmatch(r'[A-Za-z0-9_-]+', value):
        raise ValueError('Invalid provider resource identifier')
    return value


def email(value):
    value = text(value, 254)
    if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', value):
        raise ValueError('Invalid recipient email')
    return value


def prepare(provider, data, case_id, *, signwell_test_mode=False):
    if not isinstance(data, dict):
        raise ValueError('Request object required')
    request_id = identifier(data.get('request_id'))
    if provider == 'signwell':
        if set(data) != {'request_id', 'template_id', 'name', 'recipients'}:
            raise ValueError('Invalid SignWell fields')
        recipients = data['recipients']
        if not isinstance(recipients, list) or not 1 <= len(recipients) <= 20:
            raise ValueError('Recipients required')
        normalized = []
        for recipient in recipients:
            if not isinstance(recipient, dict) or set(recipient) != {'id', 'placeholder_name', 'name', 'email'}:
                raise ValueError('Invalid SignWell recipient')
            normalized.append({'id': identifier(recipient['id']),
                'placeholder_name': text(recipient['placeholder_name']),
                'name': text(recipient['name']), 'email': email(recipient['email'])})
        if len({r['id'] for r in normalized}) != len(normalized):
            raise ValueError('Duplicate recipient identifier')
        if len({r['placeholder_name'] for r in normalized}) != len(normalized):
            raise ValueError('Duplicate template placeholder')
        payload = {'template_id': identifier(data['template_id']), 'name': text(data['name']),
            'recipients': normalized, 'draft': False, 'test_mode': signwell_test_mode,
            'metadata': {'sds_case_id': case_id, 'sds_request_id': request_id}}
    elif provider == 'bluenotary':
        required = {'request_id', 'document_templates', 'all_signers', 'session_notary_email',
                    'notarization_timing_type'}
        if set(data) not in (required, required | {'session_timing'}):
            raise ValueError('Invalid BlueNotary fields')
        templates = data['document_templates']; signers = data['all_signers']
        if not isinstance(templates, list) or not 1 <= len(templates) <= 20:
            raise ValueError('Provider templates required')
        if not isinstance(signers, list) or not 1 <= len(signers) <= 20:
            raise ValueError('Signers required')
        normalized = []
        for signer in signers:
            if not isinstance(signer, dict) or set(signer) != {'first_name', 'last_name', 'email'}:
                raise ValueError('Invalid BlueNotary signer')
            normalized.append({'first_name': text(signer['first_name'], 50),
                'last_name': text(signer['last_name'], 50), 'email': email(signer['email'])})
        timing = data['notarization_timing_type']
        if timing not in ('notarize_now', 'notarize_later'):
            raise ValueError('Invalid session timing')
        payload = {'signing_type': 'ron', 'session_type': 'gnw',
            'notarization_id': hashlib.sha256((case_id + ':' + request_id).encode()).hexdigest(),
            'document_templates': [identifier(t) for t in templates], 'all_signers': normalized,
            'session_notary_email': email(data['session_notary_email']),
            'notarization_timing_type': timing}
        if timing == 'notarize_later':
            scheduled = text(data.get('session_timing'), 50)
            parsed = datetime.fromisoformat(scheduled.replace('Z', '+00:00'))
            if parsed.tzinfo is None or parsed.timestamp() <= time.time():
                raise ValueError('Future timezone-aware session time required')
            payload['session_timing'] = scheduled
        elif 'session_timing' in data:
            raise ValueError('Unexpected session time')
    else:
        raise ValueError('Unsupported provider')
    return request_id, payload


class ProviderWorkflows:
    def __init__(self, path, cases, operator, audit, clients, *, signwell_test_mode=False):
        self.path, self.cases, self.operator, self.audit, self.clients = str(path), cases, operator, audit, clients
        self.signwell_test_mode = signwell_test_mode
        with self.connect() as db:
            db.execute('''CREATE TABLE IF NOT EXISTS provider_requests (
                case_id TEXT NOT NULL, provider TEXT NOT NULL, request_id TEXT NOT NULL,
                actor TEXT NOT NULL, fingerprint TEXT NOT NULL, state TEXT NOT NULL,
                resource_id TEXT, created_at INTEGER NOT NULL,
                PRIMARY KEY(case_id,provider,request_id))''')

    def connect(self):
        db = sqlite3.connect(self.path, timeout=10); db.row_factory = sqlite3.Row
        return db

    def authorize(self, case_id, actor):
        if self.operator(actor) is not True:
            raise PermissionError('Operator required')
        self.cases.get(case_id)

    def records(self, case_id, actor):
        self.authorize(case_id, actor)
        with self.connect() as db:
            return [dict(row) for row in db.execute('''SELECT provider,request_id,state,resource_id
                FROM provider_requests WHERE case_id=? ORDER BY created_at DESC,rowid DESC LIMIT 100''', (case_id,))]

    def submit(self, case_id, actor, provider, data):
        self.authorize(case_id, actor)
        request_id, payload = prepare(provider, data, case_id, signwell_test_mode=self.signwell_test_mode)
        fingerprint = hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(',', ':'),
                                               allow_nan=False).encode()).hexdigest()
        client = self.clients.get(provider)
        if client is None:
            raise ProviderUnavailable(provider + '_credentials_not_configured')
        key = (case_id, provider, request_id)
        self.audit.preserve({'stage': 'HUMAN_PROVIDER_REQUEST', 'case_id': case_id,
            'provider': provider, 'request_id': request_id, 'actor': actor, 'sha256': fingerprint})
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            previous = db.execute('SELECT * FROM provider_requests WHERE case_id=? AND provider=? AND request_id=?', key).fetchone()
            if previous:
                if previous['fingerprint'] != fingerprint or previous['state'] != 'CREATED':
                    raise ProviderRequestConflict('Request reused or outcome requires provider reconciliation')
                return self.receipt(previous)
            db.execute('INSERT INTO provider_requests VALUES (?,?,?,?,?,?,?,?)',
                       (*key, actor, fingerprint, 'SUBMITTING', None, int(time.time())))
        try:
            result = client.create_request(payload)
            resource = identifier(result.get('id') if provider == 'signwell' else result.get('bn_session_id'))
            if provider == 'bluenotary' and result.get('response') != 'Pass':
                raise ProviderConnectionError('Provider did not accept session')
        except Exception:
            with self.connect() as db:
                db.execute('UPDATE provider_requests SET state=? WHERE case_id=? AND provider=? AND request_id=?',
                           ('OUTCOME_UNKNOWN', *key))
            self.audit.preserve({'stage': 'PROVIDER_OUTCOME_UNKNOWN', 'case_id': case_id,
                                 'provider': provider, 'request_id': request_id})
            raise ProviderUnavailable('Provider outcome unknown; inspect provider before creating another request') from None
        with self.connect() as db:
            db.execute('UPDATE provider_requests SET state=?,resource_id=? WHERE case_id=? AND provider=? AND request_id=?',
                       ('CREATED', resource, *key))
        self.audit.preserve({'stage': 'PROVIDER_REQUEST_CREATED', 'case_id': case_id,
            'provider': provider, 'request_id': request_id, 'resource_id': resource})
        return self.receipt({'provider': provider, 'request_id': request_id, 'state': 'CREATED', 'resource_id': resource})

    @staticmethod
    def receipt(record):
        return {**{k: record[k] for k in ('provider', 'request_id', 'state', 'resource_id')},
                'notarial_act_executed': False}

core_platform/security.py.content:
"""Sanders Dash & Seal: development implementation of bounded authority.

Trusted host library; does not execute payloads or claim OS/network isolation.
Production trust keys must be supplied by separately operated authorities.
"""
import base64
import hashlib
import json
import math
import secrets
import sqlite3
import time
from pathlib import Path
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat

PLATFORM = 'Sanders Dash & Seal'
ROLES = ('IT_AI_Manager_v15.0', 'MINOTAUR')

class Denied(Exception):
    """Fail-closed authorization result."""

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()

def digest(payload):
    return hashlib.sha256(payload).hexdigest()

def public_hex(key):
    return key.public_bytes(Encoding.Raw, PublicFormat.Raw).hex()

def sign(key, domain, value):
    return base64.b64encode(key.sign(domain.encode() + b'\0' + canonical(value))).decode()

def verify(key_hex, signature, domain, value):
    try:
        Ed25519PublicKey.from_public_bytes(bytes.fromhex(key_hex)).verify(
            base64.b64decode(signature, validate=True), domain.encode() + b'\0' + canonical(value))
    except Exception as exc:
        raise Denied('Invalid cryptographic proof') from exc

class TwinGate:
    def __init__(self, trusted_keys):
        if set(trusted_keys) != set(ROLES):
            raise ValueError('Two distinct trusted authority keys are required')
        decoded = {r: bytes.fromhex(k) for r, k in trusted_keys.items()}
        for value in decoded.values():
            Ed25519PublicKey.from_public_bytes(value)
        if len(set(decoded.values())) != 2:
            raise ValueError('Two distinct trusted authority keys are required')
        self.keys = {r: value.hex() for r, value in decoded.items()}

    def validate(self, domain, body, signatures):
        for role in ROLES:
            if role not in signatures:
                raise Denied('Both authorities must approve')
            verify(self.keys[role], signatures[role], domain, body)

class PBDManifestGenerator:
    @staticmethod
    def prepare(payload, artifact, scope):
        """Prepare unsigned material. This method grants no authority."""
        return {'schema': 1, 'platform': PLATFORM, 'artifact': artifact,
                'payload_hash': digest(payload), 'scope': scope}

class PBDScriptValidationEngine:
    def __init__(self, twin_gate):
        self.gate = twin_gate

    def validate(self, payload, artifact, scope, manifest):
        expected = PBDManifestGenerator.prepare(payload, artifact, scope)
        if manifest.get('body') != expected:
            raise Denied('Manifest payload, identity, or scope mismatch')
        self.gate.validate('pbd-manifest-v1', expected, manifest.get('signatures', {}))
        return expected

class Vault:
    """Durable one-use leases on one trusted SQLite host.

    No private signing keys are held here. SQLite is not an immutable store.
    """
    def __init__(self, path, twin_gate, max_lifetime, clock=time.time):
        if not max_lifetime or any(type(v) is not int or v < 1 for v in max_lifetime.values()):
            raise ValueError('Explicit positive lease lifetime policy required')
        self.max_lifetime = dict(max_lifetime)
        self.path, self.gate, self.clock = str(path), twin_gate, clock
        with self.connect() as db:
            db.executescript('''
            CREATE TABLE IF NOT EXISTS leases (
              id TEXT PRIMARY KEY, body TEXT NOT NULL, state TEXT NOT NULL);
            ''')

    def connect(self):
        return sqlite3.connect(self.path, timeout=10, isolation_level='IMMEDIATE')

    def request(self, agent_key, scope, payload, ttl, tier, requesting_agent, artifact_hash):
        from .protocol import utc, GATES, assert_record
        if type(ttl) is not int or ttl < 1:
            raise Denied('Explicit positive lease lifetime required')
        now = self.clock()
        body = {
            'lease_metadata': {'lease_id': secrets.token_hex(32),
                'timestamp_utc': utc(now), 'expires_at_utc': utc(now + ttl),
                'nonce': secrets.token_hex(32)},
            'agent_identity': {'requesting_agent': requesting_agent,
                'agent_identity_assertion': '', 'commanding_authority': 'IT_AI_Manager_v15.0'},
            'operational_bounds': {'target_endpoint': scope['endpoint'],
                'allowed_verbs': list(scope['allowed_verbs']),
                'network_jail_ips': list(scope['network_jail_ips']), 'max_execution_limit': 1},
            'dual_governance_gates': {name: '' for name in GATES},
            'execution_binding': {'agent_public_key': agent_key, 'payload_hash': digest(payload),
                'operation': scope['operation'], 'token_class': tier, 'artifact_hash': artifact_hash}}
        assert_record(body, self.max_lifetime, now)
        return body

    def mint(self, body):
        from .protocol import assert_record, signing_material, GATES
        assert_record(body, self.max_lifetime, self.clock())
        material = signing_material(body)
        self.gate.validate('pbd-lease-v2', material,
            dict(zip(ROLES, (body['dual_governance_gates'][name] for name in GATES))))
        verify(body['execution_binding']['agent_public_key'],
               body['agent_identity']['agent_identity_assertion'], 'pbd-agent-assertion-v2', material)
        lease_id = body['lease_metadata']['lease_id']
        with self.connect() as db:
            try:
                db.execute('INSERT INTO leases VALUES (?, ?, ?)',
                           (lease_id, canonical(body).decode(), 'READY'))
            except sqlite3.IntegrityError as exc:
                raise Denied('Lease already issued') from exc
        return lease_id

    def claim(self, lease_id, scope, payload, agent_proof):
        from .protocol import assert_record, check_operation
        error = None
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute('SELECT body, state FROM leases WHERE id=?', (lease_id,)).fetchone()
            if not row:
                raise Denied('Unknown lease')
            body, state = json.loads(row[0]), row[1]
            try:
                if state != 'READY':
                    raise Denied('Revoked or consumed lease')
                assert_record(body, self.max_lifetime, self.clock())
                check_operation(body, scope, payload)
                verify(body['execution_binding']['agent_public_key'], agent_proof,
                       'pbd-agent-proof-v2', {'lease': body, 'operation': scope})
            except Denied as exc:
                error = exc
            db.execute('UPDATE leases SET state=? WHERE id=?',
                       ('REVOKED' if error else 'CONSUMED', lease_id))
        if error:
            raise error
        return body

    def revoke(self, lease_id):
        with self.connect() as db:
            db.execute('UPDATE leases SET state=? WHERE id=?', ('REVOKED', lease_id))

    def state(self, lease_id):
        with self.connect() as db:
            row = db.execute('SELECT state FROM leases WHERE id=?', (lease_id,)).fetchone()
        return row[0] if row else None


class GlobalPBDSentinel:
    """Read-only integrity scanner. Containment requires a separate deployment adapter."""
    def __init__(self, validator):
        self.validator = validator

    def scan(self, root, scope):
        findings = []
        for path in sorted(Path(root).rglob('*')):
            if path.suffix not in ('.py', '.js', '.sh'):
                continue
            artifact = path.relative_to(root).as_posix()
            try:
                if path.is_symlink():
                    raise Denied('Symlink executable is not accepted')
                manifest = json.loads(Path(str(path) + '.pbd.json').read_text())
                self.validator.validate(path.read_bytes(), artifact, scope, manifest)
                status = 'VALID'
            except (OSError, ValueError, TypeError, Denied):
                status = 'BLOCKED'
            findings.append({'artifact': artifact, 'status': status})
        return findings

core_platform/sidecar_l15_contracts.py.content:
"""Sanders synthetic AI Sidecar: historical L15 contracts, fail-closed validation.

Contracts derive from the October 4, 2026 L15 disclosure. They do not
themselves supply synthetic inference, production cryptography, or deployment.
"""
import hashlib
import json

NAME = "Sanders synthetic AI Sidecar"
L15 = ("causal_reasoning", "temporal_reasoning", "counterfactual_evaluation",
       "constraint_satisfaction", "systems_reasoning", "adversarial_challenge",
       "probabilistic_uncertainty", "deterministic_verification",
       "multi_hypothesis_diagnosis", "dependency_blast_radius",
       "security_analysis", "governance_authority", "self_critique",
       "state_reconciliation", "proof_of_outcome")
SLOTS = ("current", "candidate", "previous_known_good", "recovery")
REPAIR_FIELDS = ("incident_id", "principal_id", "sidecar_id", "observed_state",
                 "expected_state", "root_cause_hypotheses", "evidence",
                 "proposed_actions", "required_capabilities", "preconditions",
                 "blast_radius", "rollback_plan", "postconditions",
                 "verification_tests", "policy_version",
                 "specification_version", "build_digest")


class SidecarContractError(ValueError):
    pass


def require_l15_evidence(evidence):
    if not isinstance(evidence, dict):
        raise SidecarContractError("L15 evidence must be an object")
    missing = [name for name in L15 if not evidence.get(name)]
    if missing:
        raise SidecarContractError("Missing L15 evidence: " + ", ".join(missing))
    return True


def require_repair_plan(plan, externally_authorized_capabilities):
    if not isinstance(plan, dict):
        raise SidecarContractError("Repair plan must be an object")
    missing = [name for name in REPAIR_FIELDS if name not in plan]
    if missing:
        raise SidecarContractError("Missing RepairPlan fields: " + ", ".join(missing))
    if not plan["principal_id"] or not plan["sidecar_id"] or plan["principal_id"] == plan["sidecar_id"]:
        raise SidecarContractError("Independent sidecar identity required")
    caps = plan["required_capabilities"]
    if not isinstance(caps, list) or any(not isinstance(cap, str) for cap in caps):
        raise SidecarContractError("Invalid capability list")
    if not set(caps).issubset(set(externally_authorized_capabilities)):
        raise SidecarContractError("Repair cannot expand its authority envelope")
    if not plan["rollback_plan"] or not plan["postconditions"] or not plan["verification_tests"]:
        raise SidecarContractError("Rollback and independent verification requirements mandatory")
    return True


class EvidenceChain:
    """In-memory hash chain for local verification, not immutable audit storage."""
    def __init__(self):
        self.records = []

    def append(self, event):
        if not isinstance(event, dict) or not event:
            raise SidecarContractError("Nonempty evidence required")
        prior = self.records[-1]["hash"] if self.records else "0" * 64
        body = {"prior": prior, "event": event}
        digest = hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()).hexdigest()
        record = {**body, "hash": digest}
        self.records.append(record)
        return record

    def verify(self):
        prior = "0" * 64
        for record in self.records:
            body = {"prior": record["prior"], "event": record["event"]}
            digest = hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()).hexdigest()
            if record["prior"] != prior or record["hash"] != digest:
                return False
            prior = digest
        return True

core_platform/sidecar_protection_gates.p.content:
"""Sanders synthetic AI Sidecar: fail-closed owner halt and crypto-readiness gates.

Development integration component. This does NOT implement post-quantum
cryptography, hardware-backed owner authentication, or a production trust root.
Those require separately verified adapters and real key material.
"""
import json
import os
import tempfile
from pathlib import Path


class ProtectionDenied(RuntimeError):
    pass


class OwnerHalt:
    """Persistent, default-halted development gate. Only the trusted local
    administrator can call resume after separately authenticating the owner.
    A caller-supplied string or bool is NOT authentication.
    """
    def __init__(self, root):
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True)
        self.path = self.root / "owner_halt.json"

    def halted(self):
        try:
            state = json.loads(self.path.read_text(encoding="utf-8"))
        except (OSError, ValueError, TypeError):
            return True
        return state.get("halted") is not False

    def _write(self, halted):
        fd, temp = tempfile.mkstemp(prefix=".halt-", dir=self.root)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as out:
                json.dump({"halted": halted}, out)
                out.flush()
                os.fsync(out.fileno())
            os.replace(temp, self.path)
        finally:
            if os.path.exists(temp):
                os.unlink(temp)

    def halt(self):
        self._write(True)

    def resume(self, owner_authenticator, proof):
        if not callable(owner_authenticator) or owner_authenticator(proof) is not True:
            raise ProtectionDenied("Independently verified owner authentication required")
        self._write(False)

    def require_running(self):
        if self.halted():
            raise ProtectionDenied("Owner halt active or halt state unavailable")


class ProtectedUpgradeExecutor:
    """Development adapter enforcing gates before staging.

    quantum_verifier must verify an actual approved PQ/hybrid cryptographic
    proof with pinned trust roots. Merely setting a 'quantum_safe' flag is not
    sufficient. No verifier means deny.
    """
    def __init__(self, executor, owner_halt, pbd_validator,
                 independent_health_verifier, quantum_verifier):
        self.executor = executor
        self.owner_halt = owner_halt
        self.pbd_validator = pbd_validator
        self.health = independent_health_verifier
        self.quantum = quantum_verifier

    def stage(self, record, artifact_path):
        self.owner_halt.require_running()
        artifact = Path(artifact_path)
        if not artifact.is_file() or artifact.is_symlink():
            raise ProtectionDenied("Regular artifact required")
        payload = artifact.read_bytes()
        evidence = record.get("evidence", {})
        manifest = evidence.get("pbd_manifest")
        scope = evidence.get("approved_scope")
        if not isinstance(manifest, dict) or not isinstance(scope, dict):
            raise ProtectionDenied("Signed PBD manifest and scope required")
        if not callable(self.pbd_validator) or self.pbd_validator(
                payload, artifact.name, scope, manifest) is not True:
            raise ProtectionDenied("Independent PBD validation failed")
        if not callable(self.quantum) or self.quantum(
                payload, record, evidence) is not True:
            raise ProtectionDenied("Post-quantum verification unavailable or failed")
        self.owner_halt.require_running()
        return self.executor.stage(record, artifact_path)

    def verify(self, record):
        self.owner_halt.require_running()
        receipt = self.executor.verify(record)
        if not isinstance(receipt, dict) or receipt.get("healthy") is not True:
            raise ProtectionDenied("Artifact verification failed")
        if not callable(self.health) or self.health(record) is not True:
            raise ProtectionDenied("Independent service health verification failed")
        return {"healthy": True, "artifact_receipt": receipt,
                "independent_service_health": True}

    def rollback(self, record):
        # Halt never prevents recovery.
        return self.executor.rollback(record)

core_platform/stream_api.py.content:
"""Signed Streaming events committed by the existing durable Python authority."""
from collections.abc import Mapping
import json

from .pipeline_api import IDENT, TransactionRejected, TransactionStore
from .receipt_verification import ReceiptSignatureVerifier, verify_and_log_receipt


def stream_signing_payload(event):
    """Exclude the signature itself; bind the independently registered actor."""
    if (not isinstance(event, dict)
            or set(event) != {'actor', 'transaction_id', 'transaction', 'signature'}
            or not isinstance(event['actor'], str) or not IDENT.fullmatch(event['actor'])
            or not isinstance(event['transaction_id'], str)
            or not IDENT.fullmatch(event['transaction_id'])
            or not isinstance(event['transaction'], dict)
            or event['transaction'].get('request_id') != event['transaction_id']
            or not isinstance(event['signature'], str) or len(event['signature']) > 256):
        raise TransactionRejected('Invalid signed event')
    return json.dumps({'actor': event['actor'], 'transaction': event['transaction']},
        sort_keys=True, separators=(',', ':'), allow_nan=False).encode()


def strict_json(raw):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError('Duplicate JSON key')
            result[key] = value
        return result
    def constant(value):
        raise ValueError('Nonfinite JSON')
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=constant)


def create_stream_app(processor=None, release_verifier=None, store=None, verifiers=None):
    """Keys and business processor come from the trusted runtime factory only."""
    def app(env, start):
        def respond(status, payload):
            raw = json.dumps(payload, separators=(',', ':'), allow_nan=False).encode()
            start(status, [('Content-Type', 'application/json'), ('Cache-Control', 'no-store'),
                          ('Content-Length', str(len(raw)))])
            return [raw]
        try:
            ready = (callable(processor) and callable(release_verifier)
                     and release_verifier() is True and isinstance(store, TransactionStore)
                     and isinstance(verifiers, Mapping) and bool(verifiers))
        except Exception:
            ready = False
        if not ready:
            return respond('503 Service Unavailable', {'error': 'stream_authority_unavailable'})
        if env.get('REQUEST_METHOD') != 'POST':
            return respond('405 Method Not Allowed', {'error': 'post_required'})
        if env.get('CONTENT_TYPE', '').split(';')[0].strip() != 'application/json':
            return respond('415 Unsupported Media Type', {'error': 'json_required'})
        try:
            length = int(env.get('CONTENT_LENGTH', '0'))
            if not 0 < length <= 262144:
                raise ValueError('Size')
            raw = env['wsgi.input'].read(length)
            if len(raw) != length:
                raise ValueError('Short body')
            event = strict_json(raw)
            payload = stream_signing_payload(event)
        except (KeyError, ValueError, TypeError, UnicodeError, RecursionError):
            return respond('400 Bad Request', {'error': 'invalid_stream_event'})
        try:
            verifier = verifiers.get(event['actor'])
            # Verify before deduplication as well: invalid signatures never get a
            # receipt just because someone previously committed the same ID.
            if (not isinstance(verifier, ReceiptSignatureVerifier)
                    or not verifier.verify(event['transaction_id'], payload, event['signature'])):
                return respond('401 Unauthorized', {'error': 'invalid_stream_signature'})

            def committed_processor(transaction, namespaced_actor, db):
                if not verify_and_log_receipt(None, event['transaction_id'], payload,
                        event['signature'], verifier=verifier, connection=db):
                    raise TransactionRejected('Signed receipt rejected')
                # Existing processor retains business validation, human authority
                # and audit duties, sharing this exact SQLite transaction.
                return processor(transaction, event['actor'], db)

            receipt = store.process(event['transaction'], 'stream:' + event['actor'], committed_processor)
            return respond('200 OK', {'transaction_id': event['transaction_id'],
                'status': 'COMMITTED', 'receipt': receipt})
        except (TransactionRejected, ValueError, TypeError):
            return respond('409 Conflict', {'error': 'stream_transaction_rejected'})
        except Exception:
            return respond('503 Service Unavailable', {'error': 'stream_commit_unavailable'})
    return app

core_platform/stripe_webhook_wsgi.py.content:
"""Fail-closed Stripe webhook ingress for Sanders Dash & Seal.

Verifies signed Stripe events before recording payment state.
Payment confirmation does not authorize or execute a notarial act.
"""
import os
from core_platform.stripe_payments import PaymentDenied, PaymentLedger, verify_stripe_webhook

MAX_BODY = 65536

def make_app(ledger, signing_secret, *, enabled=False, expected_livemode=None):
    """Return a narrow WSGI endpoint; caller must supply protected secret and ledger."""
    def app(environ, start_response):
        def respond(code, message):
            data = message.encode('ascii')
            start_response(code, [('Content-Type', 'text/plain; charset=us-ascii'),
                                  ('Content-Length', str(len(data))),
                                  ('Cache-Control', 'no-store')])
            return [data]
        if not enabled:
            return respond('503 Service Unavailable', 'Payment webhook is not configured')
        if environ.get('PATH_INFO') != '/stripe/webhook':
            return respond('404 Not Found', 'Not found')
        if environ.get('REQUEST_METHOD') != 'POST':
            return respond('405 Method Not Allowed', 'Method not allowed')
        if environ.get('CONTENT_TYPE', '').split(';')[0].strip().lower() != 'application/json':
            return respond('415 Unsupported Media Type', 'JSON required')
        try:
            n = int(environ.get('CONTENT_LENGTH', '-1'))
        except (ValueError, TypeError):
            return respond('400 Bad Request', 'Invalid length')
        if not 0 < n <= MAX_BODY:
            return respond('413 Content Too Large', 'Invalid body size')
        body = environ['wsgi.input'].read(n)
        if len(body) != n:
            return respond('400 Bad Request', 'Incomplete body')
        try:
            event = verify_stripe_webhook(body, environ.get('HTTP_STRIPE_SIGNATURE'),
                                          signing_secret)
            if expected_livemode is not None and event.get("livemode") is not expected_livemode:
                raise PaymentDenied("Payment environment mismatch")
            ledger.record_event(event)
        except PaymentDenied:
            return respond('400 Bad Request', 'Rejected')
        except Exception:
            # Storage or infrastructure failure: Stripe retries; never acknowledge.
            return respond('503 Service Unavailable', 'Processing unavailable')
        return respond('200 OK', 'Accepted')
    return app

def application(environ, start_response):
    """Deployment default is DENY, even when environment secrets exist."""
    return make_app(None, None, enabled=False)(environ, start_response)

